"""Add the separately verified official GPU backend without regenerating reviewed prose."""
from workspace import expand_runtime, run_root, runtime_path
import json,pathlib,statistics
from customer_docs import load_records,measured
B=pathlib.Path(__file__).resolve().parents[1];O=B/'report';path=B/'study/plan.json';p=json.loads(path.read_text(encoding='utf-8'));rs=load_records();data=measured(rs,'instinct');assert len(data)==6
title='Instinct Sim · Faster Action Models backend'
if not any(e['id']=='instinct'for e in p['engines']):
 p['engines'].insert(1,dict(id='instinct',title=title,use='MI350X/MI355X용 GPU 물리·카메라 backend. MuJoCo MJCF를 읽고 LIBERO·RoboCasa 실행 코드에 연결한다.',smoke='sphere–plane 500 step, 초기 50 step CPU qpos 대조, 실제 접촉·관통·유한 상태·최종 높이 확인.',performance='2048·4096·8192·16384·32768·65536 envs, native step_n(1000) × 5. 물리만 측정하며 정책·카메라 렌더링 제외.',presentation='AMD 공식 closed-loop 사례와 이번 독립 physics 처리량의 범위, C++ batch 실행 방법.',status='PASS',command='source ${LAB_ROOT}/env.sh\npython3 ${LAB_ROOT}/instinct_suite.py',source='https://github.com/AMD-AGI/faster-action-models/tree/main/simulate'))
path.write_text(json.dumps(p,ensure_ascii=False,indent=2),encoding='utf-8')
smoke=next(x for r in reversed(rs)if r['engine']=='instinct'and r['status']=='PASS'and r['case']=='instinct-smoke'for x in r['results'])
md=['## '+title,'','### 1. Simulator 설명','','AMD가 Faster Action Models에 공개한 `simulate/` backend다. MI350X/MI355X의 gfx950을 대상으로 GPU physics와 ray tracing을 제공한다. 공식 사례는 LIBERO·RoboCasa 정책 평가이며, 이번 시험은 정책과 렌더링을 제외한 독립 물리 실행이다. 이 backend를 MJWarp와 구분해 기록한다.','','### 2. Software','','#### Repositories','','- https://github.com/AMD-AGI/faster-action-models/tree/a5fa73101988870e51f04fe1e7be5da56dda3841/simulate','- https://rocm.blogs.amd.com/artificial-intelligence/faster-action-models/README.html','','#### Versions','','Source commit: `a5fa73101988870e51f04fe1e7be5da56dda3841`. CMake project version은 0.1.0이고 비교용 CPU MuJoCo는 3.3.2다. 공식 `libero` preset을 사용해 현재 SDK 10.1.0, Python 3.12.3에서 native 빌드했다. 공식 글의 ROCm 7.14/PyTorch 2.11 환경과는 다르다. native 빌드는 약 100.90 s였으며 측정 루프에 포함하지 않았다.','','빌드 플래그: `gfx950`, `HP_BOXBOX_DIST_SCALE=1`, `MJCCD_MAX_ITERATIONS=50`, `MJC_FAN_LDS_STATUS=0`, Release, 8 build jobs. 소스의 solver 수식은 수정하지 않았다. 상세 CMake 설정과 package freeze는 evidence에 보존했다.','','### 3. Throughput','','장면은 저장소 `configs/freefall.xml`의 sphere–plane, nq=7, nv=6, body=2, geom=2다. dt=0.001 s, Newton 최대 100회, tolerance=1e-8, contact/limit 활성화다. 상태 readback의 qpos dtype은 float64이고 모델의 dt·gravity 파라미터는 float32 표현값이다. 이를 다른 backend의 FP32 성능과 직접적인 우열 비율로 비교하지 않는다.','','| envs | env-step/s | steps | 중앙값 (s) | 시간 범위 (s) |','|---:|---:|---:|---:|---:|']
for r,x in sorted(data,key=lambda a:a[1]['envs']):
 ts=x['synchronized_rollout_s'];md.append(f'| {x["envs"]} | {x["env_step_per_s"]:,.2f} | {x["steps"]} | {x["median_s"]:.6f} | {min(ts):.6f}–{max(ts):.6f} |')
md+=['','#### 재현 조건','','1000 warm-up steps 뒤 초기 상태로 reset하고 1000 steps × 5회를 측정했다. C++ `step_n`을 호출하고 앞뒤에서 engine stream을 동기화했다. readback과 수치 검증은 타이머 밖이다. JSON의 `build_s`와 `compile_s`는 engine 초기화 시간을 나타내며, native CMake 빌드 시간과 구분한다.','',f'Smoke의 초기 50 step CPU qpos 최대 오차는 {smoke["early_cpu_qpos_error"]:.3e}, 최대 contact는 {smoke["max_contacts"]}개였다. 최초 smoke는 float32 gravity를 double literal과 1e-8로 비교하는 조건만 실패했다. 해당 파라미터 비교 허용오차를 1e-6으로 바로잡았고 물리 gate는 유지했다. 초기 실패·수정 후 결과를 모두 보존했다.','','```bash','source ${LAB_ROOT}/env.sh','export PYTHONPATH="$STUDY_STORAGE_ROOT/build/instinct-sim-libero/python"','export LD_LIBRARY_PATH="$STUDY_STORAGE_ROOT/build/instinct-sim-libero:$ROCM_PATH/lib:$ROCM_PATH/lib/llvm/lib"','python3 "$LAB_ROOT/instinct_suite.py"','```','','대표 직접 명령:','','```bash','"$STUDY_STORAGE_ROOT/venvs/instinct-sim/bin/python" "$LAB_ROOT/bench_instinct.py" --envs 65536 --steps 1000','```','','[공식 빌드·사용 절차](https://github.com/AMD-AGI/faster-action-models/blob/a5fa73101988870e51f04fe1e7be5da56dda3841/simulate/README.md)와 [소스 provenance](https://github.com/AMD-AGI/faster-action-models/blob/a5fa73101988870e51f04fe1e7be5da56dda3841/simulate/PROVENANCE.md)를 함께 제공한다. LIBERO·RoboCasa 전체 평가, OSC controller와 ray tracer의 정확도·성능은 이번 물리 시험 범위 밖이다.','','### 4. Throughput plot','','![Instinct Sim throughput](images/instinct-throughput-0.png)','']
body='\n'.join(md);(O/'instinct-addendum-input.md').write_text(body,encoding='utf-8')
current=(O/'confluence-report.md').read_text(encoding='utf-8')
current=current.replace('추가 Taichi·GSplat을 포함한 12개 탭에서 총 49개 성능 구성 × 5회','추가 Taichi·GSplat·Instinct Sim을 포함한 13개 탭에서 총 55개 성능 구성 × 5회')
if '## '+title not in current:current=current.replace('## Genesis World',body+'\n## Genesis World',1)
(O/'confluence-report.md').write_text(current,encoding='utf-8')
print('Added official backend:',len(data),'measured configurations')
